<?php require_once 'config.php';$featured=$pdo->query("SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC LIMIT 4")->fetchAll();$cats=$pdo->query("SELECT * FROM categories")->fetchAll();$title='Home';include 'header.php';?><section class="hero mb-5"><p class="text-uppercase">A softer kind of self-care</p><h1>Bloom into your beautiful.</h1><p>Discover feel-good beauty essentials, thoughtfully picked for your everyday rituals.</p><a class="btn btn-rose mt-3" href="shop.php">SHOP THE COLLECTION</a></section><div class="text-center mb-4"><p class="muted">FIND YOUR FAVOURITES</p><h2>Shop by category</h2></div><div class="row g-3 mb-5"><?php foreach($cats as $c): ?><div class="col-6 col-md-3"><a class="text-decoration-none text-dark" href="shop.php?category=<?= $c['id'] ?>"><div class="panel text-center"><h5><?= h($c['name']) ?></h5></div></a></div><?php endforeach; ?></div><h2 class="mb-4">Featured favourites</h2><div class="row g-4"><?php foreach($featured as $p): ?><div class="col-6 col-md-3"><div class="card"><a href="product.php?id=<?= $p['id'] ?>"><img class="card-img-top" src="<?= h($p['image_url']) ?>"></a><div class="card-body"><small class="muted"><?= h($p['category']) ?></small><h5><?= h($p['name']) ?></h5><p class="price"><?= money($p['price']) ?></p><a class="btn btn-rose" href="product.php?id=<?= $p['id'] ?>">View product</a></div></div></div><?php endforeach; ?></div><?php include 'footer.php'; ?>
